def set_paragraph_text(paragraph, value):
    paragraph.clear()
    paragraph.add_run(value)


def insert_after(paragraph, value):
    new_element = deepcopy(paragraph._p)
    paragraph._p.addnext(new_element)
    new_paragraph = Paragraph(new_element, paragraph._parent)
    set_paragraph_text(new_paragraph, value)
    return new_paragraph


document = Document(SOURCE)
anchors = {}

for paragraph in document.paragraphs:
    text = paragraph.text.strip()
    for prefix, replacement in REPLACEMENTS.items():
        if text.startswith(prefix):
            set_paragraph_text(paragraph, replacement)
            break
    for prefix in ("3.8.", "7.14.", "9.5."):
        if text.startswith(prefix):
            anchors[prefix] = paragraph

if set(anchors) != {"3.8.", "7.14.", "9.5."}:
    raise RuntimeError("Required insertion point was not found")

insert_after(anchors["3.8."], NEW_381)
insert_after(anchors["7.14."], NEW_7141)
insert_after(anchors["9.5."], NEW_951)

OUTPUT.parent.mkdir(parents=True, exist_ok=True)
document.save(OUTPUT)
